cess'=>'Znovu otvoriť a povoliť nový hromadný export','Open details and editing interface for submission %d'=>'Otvoriť podrobnosti a rozhranie na úpravu odoslania %d','button: open the submission to view it (verb)Open'=>'Otvoriť','Close'=>'Zatvoriť','Only Submissions processed via Ninja Forms can be edited at the moment.'=>'Momentálne je možné upravovať iba odoslania spracované pluginom Ninja Forms.','Fieldset %d'=>'Skupina polí %d','No values entered in this field'=>'Do tohto poľa nie sú zadané žiadne hodnoty','File Upload Link %s'=>'Odkaz na nahraný súbor %s','Submission\'s meta data'=>'Metaúdaje odoslania','Link to the post editing page for submission %d'=>'Odkaz na stránku úpravy článku pre odoslanie %d','Submission Key'=>'Kľúč odoslania','Submitted at'=>'Čas odoslania','Original Form ID'=>'Jedinečné ID formulára','Loading Form'=>'Nahrávam formulár','This form has no submissions.'=>'Tento formulár nemá žiadne odoslania.','%d submission in the form'=>'%d odoslanie vo formulári' . "\0" . '%d odoslania vo formulári' . "\0" . '%d odoslaní vo formulári','%d submission filtered'=>'Vyfiltrované %d odoslanie' . "\0" . 'Vyfiltrované %d odoslania' . "\0" . 'Vyfiltrovaných %d odoslaní','Navigate to first page'=>'Prejsť na prvú stránku','Navigate to previous page'=>'Prejsť na predchádzajúcu stránku','Navigate to next page'=>'Prejsť na ďalšiu stránku','Navigate to last page'=>'Prejsť na poslednú stránku','Page %1$d of %2$d'=>'Stránka %1$d z %2$d','Go to page:'=>'Ísť na stránku:','Select the page number to navigate to'=>'Vyberte číslo stránky, na ktorú chcete prejsť','Set number of submissions to display per page.'=>'Nastavte počet odoslaní zobrazených na jednej stránke.','Show %d'=>'Zobraziť %d','Display Columns control'=>'Zobraziť ovládanie stĺpcov','Unselect to hide corresponding column'=>'Zrušením výberu skryjete príslušný stĺpec','No Submissions matching the request.'=>'Požiadavke nezodpovedajú žiadne odoslania.','Submissions Status'=>'Stav odoslaní','Enter Search Term...'=>'Zadajte hľadaný výraz...','Filter Submissions'=>'Filtrovať odoslania','Reset Filters'=>'Resetovať filtre','Submission successfully exported'=>'Odoslanie bolo úspešne exportované','The export failed. Contact a developer or check the logs if this failure persists.'=>'Export zlyhal. Ak chyba pretrváva, kontaktujte vývojára alebo si pozrite protokoly.','Export submission %d via CSV file'=>'Exportovať odoslanie %d do súboru CSV','Move submission %d to the Trash'=>'Presunúť odoslanie %d do koša','Delete Submission %d'=>'Vymazať odoslanie %d','Delete Submission Permanently'=>'Vymazať odoslanie natrvalo','Restore submission %d'=>'Obnoviť odoslanie %d']];